5	namespace AtrioTeam\DigitalHub\Pim\Concerns;
6	
7	use AtrioTeam\DigitalHub\Pim\AttributeSchema;
8	use Illuminate\Database\Eloquent\Builder;
9	
10	/**
11	 * Trait universale per modelli con attributi PIM su colonna JSON.
12	 *
13	 * Configurazione lato modello (entrambi opzionali):
14	 *   protected static string $attributesColumn = 'properties';     // default 'properties'
15	 *   protected static ?string $attributeSchemaClass = ProductAttributes::class;
16	 *
17	 * Nota sul nome della colonna: il default è 'properties', non 'attributes',
18	 * di proposito. Una colonna chiamata 'attributes' collide con la proprietà
19	 * dichiarata Eloquent Model::$attributes: l'accesso dinamico bypasserebbe il
20	 * cast e i metodi del trait leggerebbero l'intero array di attributi del
21	 * modello invece del JSON. Evitare di reintrodurre quel nome.
22	 *
23	 * Per risoluzione dinamica dello schema (es. in base a categoria) si può
24	 * sovrascrivere resolveAttributeSchemaClass() nel modello.
25	 *
26	 * Nota: il trait NON dichiara queste static properties — i modelli le
27	 * dichiarano direttamente. Questo evita il PHP property compatibility check
28	 * tra trait e classe usante.
29	 *
30	 * @mixin \Illuminate\Database\Eloquent\Model
31	 */
32	trait HasTechnicalAttributes
33	{
34	    public function initializeHasTechnicalAttributes(): void
35	    {
36	        $this->mergeCasts([$this->attributesColumn() => 'array']);
37	    }
38	
39	    public function resolveAttributeSchemaClass(): ?string
40	    {
41	        return property_exists(static::class, 'attributeSchemaClass')
42	            ? static::$attributeSchemaClass
43	            : null;
44	    }
45	
46	    public function attributeSchema(): ?AttributeSchema
47	    {
48	        $class = $this->resolveAttributeSchemaClass();
49	        if ($class === null) {
50	            return null;
51	        }
52	
53	        /** @var AttributeSchema $instance */
54	        $instance = new $class();
55	
56	        return $instance;
57	    }
58	
59	    public function attributesColumn(): string
60	    {
61	        if (! property_exists(static::class, 'attributesColumn')) {
62	            return 'properties';
63	        }
64	
65	        $column = static::$attributesColumn;
66	
67	        return is_string($column) ? $column : 'properties';
68	    }
69	
70	    /**
71	     * Valore corrente della colonna attributi come array.
72	     *
73	     * Passa esplicitamente da getAttribute() (sistema cast di Eloquent) invece
74	     * dell'accesso dinamico $this->{column}: quest'ultimo è ambiguo se il nome
75	     * della colonna coincide con una proprietà dichiarata del Model (es.
76	     * 'attributes' → Model::$attributes), nel qual caso bypasserebbe il cast.
77	     * Il default 'properties' evita la collisione, ma il modello può scegliere
78	     * qualunque nome: getAttribute()/setAttribute() restano corretti comunque.
79	     *
80	     * @return array<string, mixed>
81	     */
82	    private function attributeValues(): array
83	    {
84	        $values = $this->getAttribute($this->attributesColumn());
85	
86	        /** @var array<string, mixed> $values */
87	        $values = is_array($values) ? $values : [];
88	
89	        return $values;
90	    }
91	
92	    /**
93	     * Scrive l'array dei valori sulla colonna attributi via setAttribute()
94	     * (vedi attributeValues() per il motivo del cast esplicito).
95	     *
96	     * @param array<string, mixed> $values
97	     */
98	    private function setAttributeValues(array $values): void
99	    {
100	        $this->setAttribute($this->attributesColumn(), $values);
101	    }
102	
103	    /**
104	     * Chiavi presenti nel JSON degli attributi che NON hanno più posto nello
105	     * schema dato (orfani). Se $schema è null, tutte le chiavi sono orfane:
106	     * un modello senza schema non ammette alcun attributo tipizzato.
107	     *
108	     * Lo schema va passato esplicitamente perché il chiamante può volerlo
109	     * confrontare con uno schema diverso da quello attualmente risolto sul
110	     * record (es. la tipologia appena scelta nel form, non ancora persistita).
111	     *
112	     * @return list<string>
113	     */
114	    public function orphanAttributeKeys(?AttributeSchema $schema): array
115	    {
116	        $values = $this->attributeValues();
117	        $validKeys = $schema !== null ? array_keys($schema->attributes()) : [];
118	
119	        return array_values(array_diff(array_keys($values), $validKeys));
120	    }
121	
122	    /**
123	     * Il JSON degli attributi ripulito dalle chiavi orfane rispetto allo
124	     * schema dato. Non muta il record: ritorna l'array da assegnare.
125	     *
126	     * @return array<string, mixed>
127	     */
128	    public function stripOrphanAttributes(?AttributeSchema $schema): array
129	    {
130	        $values = $this->attributeValues();
131	        $orphans = $this->orphanAttributeKeys($schema);
132	
133	        return array_diff_key($values, array_flip($orphans));
134	    }
135	
136	    /**
137	     * Legge un attributo. Se è translatable e il valore è un map locale→valore,
138	     * restituisce il valore per la locale richiesta (o fallback).
139	     */
140	    public function attr(string $key, ?string $locale = null): mixed
141	    {
142	        $values = $this->attributeValues();
143	        $raw = $values[$key] ?? null;
144	
145	        $type = $this->attributeSchema()?->getType($key);
146	        if ($type?->isTranslatable() && is_array($raw)) {
147	            $locale ??= app()->getLocale();
148	            $fallback = config('app.fallback_locale');
149	            $fallback = is_string($fallback) ? $fallback : '';
150	
151	            return $raw[$locale] ?? $raw[$fallback] ?? null;
152	        }
153	
154	        return $raw;
155	    }
156	
157	    public function setAttr(string $key, mixed $value): static
158	    {
159	        $values = $this->attributeValues();
160	        $values[$key] = $value;
161	        $this->setAttributeValues($values);
162	
163	        return $this;
164	    }
165	
166	    /**
167	     * Label tradotta dell'attributo via i18n.
168	     * Chiave: {modello}.attributes.{attr}.label   (un file per entità in lang/{locale}/)
169	     * Fallback: la chiave grezza dell'attributo.
170	     */
171	    public function attrLabel(string $key): string
172	    {
173	        $modelKey = \Illuminate\Support\Str::snake(class_basename(static::class));
174	        $translationKey = "{$modelKey}.attributes.{$key}.label";
175	        $translated = __($translationKey);
176	
177	        return is_string($translated) && $translated !== $translationKey ? $translated : $key;
178	    }
179	
180	    /**
181	     * Label tradotta di una opzione enum.
182	     * Chiave: {modello}.attributes.{attr}.options.{option}.
183	     * Fallback: la chiave grezza dell'opzione.
184	     */
185	    public function attrOption(string $key, string $option): string
186	    {
187	        $modelKey = \Illuminate\Support\Str::snake(class_basename(static::class));
188	        $translationKey = "{$modelKey}.attributes.{$key}.options.{$option}";
189	        $translated = __($translationKey);
190	
191	        return is_string($translated) && $translated !== $translationKey ? $translated : $option;
192	    }
193	
194	    /**
195	     * Label tradotta di un gruppo (Tab).
196	     * Chiave: {modello}.attributes.groups.{group}.
197	     * Fallback: ucfirst della chiave grezza.
198	     */
199	    public function attrGroupLabel(string $group): string
200	    {
201	        $modelKey = \Illuminate\Support\Str::snake(class_basename(static::class));
202	        $translationKey = "{$modelKey}.attributes.groups.{$group}";
203	        $translated = __($translationKey);
204	
205	        return is_string($translated) && $translated !== $translationKey ? $translated : ucfirst($group);
206	    }
207	
208	    /**
209	     * @param Builder<static> $query
210	     * @return Builder<static>
211	     */
212	    public function scopeWhereAttr(Builder $query, string $key, mixed $value): Builder
213	    {
214	        return $query->where("{$this->attributesColumn()}->{$key}", $value);
215	    }
216	
217	    /**
218	     * @param Builder<static> $query
219	     * @return Builder<static>
220	     */
221	    public function scopeWhereAttrBetween(Builder $query, string $key, mixed $min, mixed $max): Builder
222	    {
223	        return $query->whereBetween("{$this->attributesColumn()}->{$key}", [$min, $max]);
224	    }
225	}
