5	namespace AtrioTeam\DigitalHub\Identity\Concerns;
6	
7	use Illuminate\Database\Eloquent\Model;
8	
9	/**
10	 * Generates and stores a stable, human-readable global identifier on creation.
11	 *
12	 * Format: {table}:{id} (e.g. categories_1:21, products:5)
13	 *
14	 * The global_id is:
15	 * - generated automatically after insert (requires the DB-assigned primary key)
16	 * - immutable: never updated after creation
17	 * - unique across the table
18	 *
19	 * Requires column: global_id VARCHAR unique nullable
20	 *
21	 * @property string|null $global_id
22	 *
23	 * @mixin Model
24	 */
25	trait HasGlobalId
26	{
27	    public static function bootHasGlobalId(): void
28	    {
29	        static::saved(function (Model $model): void {
30	            /** @var static $model */
31	            if ($model->global_id === null) {
32	                $key = $model->getKey();
33	                $key = is_scalar($key) ? (string) $key : '';
34	                $model->global_id = $model->getTable() . ':' . $key;
35	                $model->saveQuietly();
36	            }
37	        });
38	    }
39	}
