5	namespace Tests\Feature\Api;
6	
7	use App\Models\Designer;
8	use Illuminate\Foundation\Testing\RefreshDatabase;
9	use Tests\TestCase;
10	
11	/**
12	 * API esterna di lettura consumata in pull dal CMS a valle (roadmap #24).
13	 * Il designer è la prima entità esposta: tracer bullet del contratto
14	 * (auth a token, locale, global_id, sync incrementale).
15	 */
16	class DesignerApiTest extends TestCase
17	{
18	    use RefreshDatabase;
19	
20	    private const TOKEN = 'test-token';
21	
22	    protected function setUp(): void
23	    {
24	        parent::setUp();
25	
26	        config(['digital-hub.api.tokens' => 'atmosphera-admin:' . self::TOKEN . ',altro-cms:altro-token']);
27	    }
28	
29	    public function test_it_rejects_a_request_without_a_valid_token(): void
30	    {
31	        $this->getJson('/api/v1/designers')->assertUnauthorized();
32	
33	        $this->withToken('sbagliato')->getJson('/api/v1/designers')->assertUnauthorized();
34	    }
35	
36	    public function test_it_lists_designers_with_the_global_id_as_join_key(): void
37	    {
38	        $designer = $this->makeDesigner(['it' => 'Mario Rossi', 'en' => 'Mario Rossi'], 'mario-rossi');
39	
40	        $this->withToken(self::TOKEN)
41	            ->getJson('/api/v1/designers')
42	            ->assertOk()
43	            ->assertJsonPath('data.0.global_id', $designer->global_id)
44	            ->assertJsonPath('data.0.slug', 'mario-rossi')
45	            ->assertJsonPath('meta.total', 1);
46	    }
47	
48	    public function test_it_resolves_translations_in_the_requested_locale(): void
49	    {
50	        $this->makeDesigner(['it' => 'Studio Bianco', 'en' => 'White Studio'], 'studio-bianco');
51	
52	        $this->withToken(self::TOKEN)
53	            ->getJson('/api/v1/designers?locale=en')
54	            ->assertOk()
55	            ->assertJsonPath('data.0.name', 'White Studio');
56	    }
57	
58	    public function test_it_returns_a_single_designer_by_global_id(): void
59	    {
60	        $designer = $this->makeDesigner(['it' => 'Mario Rossi'], 'mario-rossi');
61	
62	        $this->withToken(self::TOKEN)
63	            ->getJson('/api/v1/designers/' . $designer->global_id)
64	            ->assertOk()
65	            ->assertJsonPath('data.slug', 'mario-rossi');
66	
67	        $this->withToken(self::TOKEN)
68	            ->getJson('/api/v1/designers/designers:999')
69	            ->assertNotFound();
70	    }
71	
72	    public function test_it_filters_by_updated_since_for_incremental_sync(): void
73	    {
74	        $old = $this->makeDesigner(['it' => 'Vecchio'], 'vecchio');
75	        $old->forceFill(['updated_at' => now()->subMonth()])->saveQuietly();
76	
77	        $recent = $this->makeDesigner(['it' => 'Nuovo'], 'nuovo');
78	
79	        $this->withToken(self::TOKEN)
80	            ->getJson('/api/v1/designers?updated_since=' . urlencode(now()->subDay()->toIso8601String()))
81	            ->assertOk()
82	            ->assertJsonCount(1, 'data')
83	            ->assertJsonPath('data.0.global_id', $recent->global_id);
84	    }
85	
86	    public function test_it_hides_entities_not_declared_in_the_registry(): void
87	    {
88	        $this->withToken(self::TOKEN)
89	            ->getJson('/api/v1/users')
90	            ->assertNotFound();
91	    }
92	
93	    /**
94	     * @param array<string, string> $name
95	     */
96	    private function makeDesigner(array $name, string $slug): Designer
97	    {
98	        return Designer::create(['name' => $name, 'slug' => $slug]);
99	    }
100	}
